import { isNull, loadProperty } from "@tsparticles/engine";
import { InfectionStage } from "./InfectionStage.js";
export class Infection {
    cure;
    delay;
    enable;
    infections;
    stages;
    constructor() {
        this.cure = false;
        this.delay = 0;
        this.enable = false;
        this.infections = 0;
        this.stages = [];
    }
    load(data) {
        if (isNull(data)) {
            return;
        }
        loadProperty(this, "cure", data.cure);
        loadProperty(this, "delay", data.delay);
        loadProperty(this, "enable", data.enable);
        loadProperty(this, "infections", data.infections);
        if (data.stages === undefined) {
            return;
        }
        this.stages = data.stages.map(t => {
            const s = new InfectionStage();
            s.load(t);
            return s;
        });
    }
}
